// Client-side enchant/event-monster skill DoFunc that spawns a delayed chain of missiles along the line from the caster to its target coordinates. Validates the skill and its cltmissileb missile record, gets the target coords (GetCooordinates) and line distance, then steps along the line at Param1 spacing casting cltmissileb missiles (CastAttack), each given an increasing total/current-frame delay (Param2 step) and set NODRAW so they activate sequentially. Finally fires the primary cltmissilea missile (CastAttackWithDistanceCheck), offsetting its activation frame by the accumulated chain delay so it lands after the line. Returns TRUE on success.
BOOL __fastcall Skills_CltDoFunc_EMon_DelayedLineMissileChain(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    D2UnitStrc* pMissile;
    int32_t nChainBaseTotalFrames;
    int nUnitY;
    int nUnitScaledDeltaY;
    int nScaledDeltaY;
    int32_t nDestY;
    int32_t nDestX;
    int nChainFrameDelay;
    if ((int)eSkill < 0) {
      return 0;
    }
    if ((int)eSkill >= sgptDataTable->nTxtSkillsCount) {
      return 0;
    }

    D2SkillsTxt* pSkillsTxt = sgptDataTable->pTxtSkills + eSkill;
    if (!pSkillsTxt) {
      return 0;
    }

    eMissilesId eMissileChainId = (eMissilesId)pSkillsTxt->cltmissile[2];
    if (!((int)eMissileChainId >= 0 && (int)eMissileChainId < sgptDataTable->nTxtMissilesSize)) {
      return 0;
    }

    D2MissilesTxt* pMissileTxt = sgptDataTable->pTxtMissiles + eMissileChainId;
    if (!pMissileTxt) {
      return 0;
    }

    eD2Skills eSavedSkill = eSkill;
    BOOL bGotCoords = Skills::GetCooordinates(pUnit, &nDestX, &nDestY);
    if (!bGotCoords) {
      return 0;
    }

    int32_t nDistance = D2Common::Collision::GetDistanceToXY(pUnit, nDestX, nDestY);
    if (nDistance < 1) {
      nDistance = 1;
    }

    int32_t nCalcA = Units::GetXPosFromDynamicPathUnit(pUnit);
    int32_t nUnitX = Units::GetYPosFromDynamicPathUnit(pUnit);
    int nScaledDeltaX = (nDestX - nCalcA) * 100 / nDistance;
    int nCurDist = pMissileTxt->Param1;
    if (nCurDist < 1) {
      nCurDist = 1;
    }

    int nChainFrameStep = 1;
    if (pMissileTxt->Param2 >= 1) {
      nChainFrameStep = pMissileTxt->Param2;
    }

    int nSpawnedChainCount = 0;
    int nChainSpacing = nCurDist;
    if (nCurDist < nDistance) {
      uint8_t byChainDir;
      nChainFrameDelay = 0;
      nUnitY = nCurDist * nScaledDeltaX;
      nUnitScaledDeltaY = nCurDist * ((nDestY - nUnitX) * 100 / nDistance);
      nScaledDeltaY = nUnitScaledDeltaY;
      nScaledDeltaX = nUnitY;
      do {
        pMissile = UNIT::Missile::CastAttack(pUnit, eMissileChainId, nScaledDeltaX / 100 + nCalcA, nScaledDeltaY / 100 + nUnitX, eSavedSkill, nSkillLvl);
        if (pMissile) {
          byChainDir = D2Common::Units::GetDirection(pUnit);
          D2Common::PATH::DynamicPath::PATH_SetNewDirection(pMissile->pPath.pDynamicPath, byChainDir);
          nChainBaseTotalFrames = D2Common::Units::Missile::GetTotalFrames(pMissile);
          D2Common::Units::Missile::SetTotalFrames(pMissile, nChainFrameDelay + nChainBaseTotalFrames);
          D2Common::Units::Missile::SetCurrentFrame(pMissile, nChainFrameDelay + nChainBaseTotalFrames);
          D2Common::Units::Missile::SetActivateFrame(pMissile, nChainBaseTotalFrames - nChainFrameDelay);
          pMissile->eUnitFlagsEx |= UNITFLAGEX_NODRAW;
        }

        nCurDist += nChainSpacing;
        nScaledDeltaY += nUnitScaledDeltaY;
        nScaledDeltaX += nUnitY;
        nSpawnedChainCount++;
        nChainFrameDelay += nChainFrameStep;
      } while (nCurDist < nDistance);
    }

    eMissileChainId = (eMissilesId)pSkillsTxt->cltmissile[1];
    if (!((int)eMissileChainId >= 0 && (int)eMissileChainId < sgptDataTable->nTxtMissilesSize)) {
      return 1;
    }

    pMissile = Skills::CastAttackWithDistanceCheck(pUnit, eMissileChainId, eSavedSkill, nSkillLvl);
    if (!pMissile) {
      return 0;
    }

    nCalcA = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxt->calc[0], eSavedSkill, nSkillLvl);
    if (nCalcA > 0) {
      D2Common::Units::SetAnimationSpeed(pMissile, nCalcA);
    }

    nCalcA = D2Common::Units::Missile::GetTotalFrames(pMissile);
    nUnitY = nSpawnedChainCount * nChainFrameStep;
    nScaledDeltaY = nUnitY + nCalcA;
    D2Common::Units::Missile::SetTotalFrames(pMissile, nScaledDeltaY);
    D2Common::Units::Missile::SetCurrentFrame(pMissile, nScaledDeltaY);
    D2Common::Units::Missile::SetActivateFrame(pMissile, nCalcA - nUnitY);
    pMissile->eUnitFlagsEx |= UNITFLAGEX_NODRAW;
    return 1;
}

BOOL __fastcall Skills_CltStFunc_SetTimedDurationAndInfernoState(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillsTxtBase = sgptDataTable->pTxtSkills;
    if (!(pSkillsTxtBase + eSkill)) {
      return 0;
    }

    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    int32_t nDuration = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxtBase[eSkill].calc[1], eSkill, nSkillLvl);
    if (nDuration < 1) {
      nDuration = 1;
    }

    int32_t nGameTick = GAME::Game::GetEntryIndex();
    D2Common::Skills::SKILL_SetParam1(pSkill, nGameTick + nDuration);
    eD2States eInfernoState = D2Common::DATATBLS::ItemStats::UNIT_GetUnitState(pUnit, STATE_inferno);
    if (eInfernoState != STATE_none) {
      return 1;
    }

    D2Common::DATATBLS::ItemStats::SetState(pUnit, STATE_inferno, 1);
    return 1;
}

// Client DoFunc for EMon Inferno-style skills with Z elevation. Checks the skill's Param1 against the current game entry index to decide whether to clear the STATE_inferno state or create an inferno missile via SKILLSSOR_CltCreateInfernoMissile. If created, sets particle Z from cltcalc[0] and enables reverse direction. Clears UNITFLAG_SKSRVDOFUNC on success.
BOOL __fastcall Skills_CltDoFunc_EMon_InfernoWithZ(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    int32_t nPosZ;
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillTxt = sgptDataTable->pTxtSkills;
    if (!(pSkillTxt + eSkill)) {
      return 0;
    }

    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    uint32_t nParam1 = D2Common::Skills::SKILL_GetParam1(pSkill);
    uint32_t nEntryIndex = GAME::Game::GetEntryIndex();
    if (nEntryIndex > nParam1) {
      D2Common::DATATBLS::ItemStats::SetState(pUnit, STATE_inferno, 0);
    } else {
      D2UnitStrc* pInfernoMissile;
      pInfernoMissile = SkillsSor::SKILLSSOR_CltCreateInfernoMissile(pUnit, eSkill, nSkillLvl);
      if (pInfernoMissile) {
        Engine::Particle::AllocParticle(pInfernoMissile);
        nPosZ = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillTxt[eSkill].cltcalc[0], eSkill, nSkillLvl);
        Engine::Particle::SetPosVectorShifted(pInfernoMissile, 0, 0, nPosZ);
        Engine::Particle::PARTICLE_SetReverseDirection(pInfernoMissile, 1);
        if (!pUnit) {
          return 1;
        }

        pUnit->eUnitFlags &= ~UNITFLAG_SKSRVDOFUNC;
        return 1;
      }
    }

    return 0;
}

// Client StFunc: reads the confirmed target unit's map X/Y position and stores them into the current skill's Param1/Param2. Used by EMon skills so subsequent DoFunc calls can fire missiles at the remembered target coordinates rather than the live target position.
BOOL __fastcall Skills_CltStFunc_SetParamsFromTargetPositionEMon(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    int nPosX;
    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    D2UnitStrc* pTarget = UNIT::CUnit::GetConfirmedTargetUnit(pUnit);
    if (!pTarget) {
      return 0;
    }

    eD2UnitType eTargetType = pTarget->eUnitType;
    if (eTargetType == UNIT_OBJECT || (int)eTargetType > 3 && (int)eTargetType <= 5) {
      nPosX = pTarget->pPath.pStaticPath->nPosX;
    } else if (pTarget->pPath.pDynamicPath) {
      nPosX = D2Common::PATH::DynamicPath::GetXPos(pTarget->pPath.pDynamicPath);
    } else {
      nPosX = 0;
    }

    D2Common::Skills::SKILL_SetParam1(pSkill, nPosX);
    eTargetType = pTarget->eUnitType;
    if (eTargetType != UNIT_OBJECT && ((int)eTargetType <= 3 || (int)eTargetType > 5)) {
      int32_t nTargetY;
      if (pTarget->pPath.pDynamicPath) {
        nTargetY = D2Common::PATH::DynamicPath::GetYPos(pTarget->pPath.pDynamicPath);
        D2Common::Skills::SKILL_SetParam2(pSkill, nTargetY);
        return 1;
      }

      D2Common::Skills::SKILL_SetParam2(pSkill, 0);
      return 1;
    }

    D2Common::Skills::SKILL_SetParam2(pSkill, pTarget->pPath.pStaticPath->nPosY);
    return 1;
}

// Client DoFunc that fires the skill's cltmissilea (and optionally cltmissileb) at the map coordinates stored in skill Param1/Param2 (set by Skills_CltStFunc_SetParamsFromTargetPositionEMon). Plays prgsound on the primary missile. Returns TRUE if at least the primary missile was created.
BOOL __fastcall Skills_CltDoFunc_EMon_MissileAtParam(D2UnitStrc * pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
    if (!((int)eSkill >= 0 && (int)eSkill < sgptDataTable->nTxtSkillsCount)) {
      return 0;
    }

    D2SkillsTxt* pSkillTxt = sgptDataTable->pTxtSkills + eSkill;
    if (!pSkillTxt) {
      return 0;
    }

    D2SkillStrc* pSkill = D2Common::Units::GetCurrentSkill(pUnit);
    if (!pSkill) {
      return 0;
    }

    int32_t nX = D2Common::Skills::SKILL_GetParam1(pSkill);
    int32_t nY = D2Common::Skills::SKILL_GetParam2(pSkill);
    if (!(nX && nY)) {
      return 0;
    }

    eMissilesId eMissileId = (eMissilesId)pSkillTxt->cltmissile[1];
    if ((int)eMissileId >= 0 && (int)eMissileId < sgptDataTable->nTxtMissilesSize) {
      D2UnitStrc* pMissile;
      pMissile = UNIT::Missile::CastAttack(pUnit, eMissileId, nX, nY, eSkill, nSkillLvl);
      if (!pMissile) {
        return 0;
      }
      if (pSkillTxt->prgsound > 0) {
        Sound::SOUND_PlaySound((int)pSkillTxt->prgsound, pMissile, 0, 0, 0);
      }
    }

    eMissileId = (eMissilesId)pSkillTxt->cltmissile[2];
    if (!((int)eMissileId >= 0 && (int)eMissileId < sgptDataTable->nTxtMissilesSize)) {
      return 1;
    }

    UNIT::Missile::CastAttack(pUnit, eMissileId, nX, nY, eSkill, nSkillLvl);
    return 1;
}

